    // ---------- Find a capture device ----------
    int32 DeviceCount = 0;
    FAudioCaptureDevice::GetDeviceCount(&DeviceCount);

    for (int32 Index = 0; Index < DeviceCount; ++Index)
    {
        TSharedPtr<FAudioCaptureDevice> Device;
        if (FAudioCaptureDevice::Create(Index, Device))
